const translationPattern=new RegExp(Object.keys(english).sort((a,b)=>b.length-a.length).map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
function translate(html){if(language==='es')return html;return html.replace(translationPattern,key=>english[key]).replace(/Respiración (\d) de 3/g,'Breath $1 of 3').replace(/Frase (\d) de 3/g,'Phrase $1 of 3').replace(/Página (\d) de 3/g,'Page $1 of 3').replace(/Carta (\d)/g,'Card $1').replace(/Parejas encontradas: (\d) de 4/g,'Pairs found: $1 of 4').replace(/ADAPTACIÓN BREVE · LIBRO (\d)/g,'BRIEF ADAPTATION · BOOK $1');}
const adventuresEn={
enojo:{label:'Anger',title:'The Tower That Fell',story:['Tilo, the little red-bearded elephant, was building a block tower with Luma, his turtle friend. When they placed the last block, the tower fell. Tilo’s cheeks felt hot, his trunk stiffened and his beard began to bristle.','Tilo shouted at Luma and nearly threw a block. Then he saw his reflection in a puddle. He put the block down, stepped away and named his feelings: anger and frustration. He took a moment to breathe slowly.','When he was ready, Tilo spoke to Luma again. He admitted that shouting was wrong, apologized and listened to how she felt. They decided to try again with a wider base, letting each other know before moving a block.'],questions:['What changes do you notice in your body when you feel angry?']},
miedo:{label:'Fear',title:'The Firefly Path',story:['Tilo wanted to see the path lit by fireflies. To reach it, he had to cross the forest as it grew dark. He felt afraid but tried to hide it. Along the way, he became separated from Luma.','With Chispita’s help, Tilo learned to notice his body’s signals and say how he felt. He could breathe, ask for help and look at the next step without having to see the whole path.','Tilo discovered that being brave doesn’t mean pretending nothing scares us. With company and little steps, he could find a way to explore what he wanted to discover.'],questions:['What signals does your body give you when you feel afraid?']},
tristeza:{label:'Sadness',title:'After the Rain',story:['Tilo found Luma feeling sad beside the pond. He tried to cheer her up with games, fruit and races, but she didn’t feel like joining in. Chispita showed him that they could listen to a feeling before trying to make it go away.','Luma remembered the yellow flower she had cared for since it was a seed. A storm had damaged it. When someone said it was only a flower, she felt as though her feelings didn’t matter either.','Tilo and Chispita listened without rushing Luma or asking her to smile. Tilo understood how much the flower had meant to her and offered a hug. Luma could cry and share her sadness, feeling supported and understood.'],questions:['How could you approach someone who seems sad?']},
celos:{label:'Jealousy and talents',title:'Each in Their Own Way',story:['At the Talent Festival, Tilo’s friends each had something to share. Tilo began comparing himself to them and felt that his own talent wasn’t special enough. His friends’ sparkle seemed like a threat.','Tilo had to recognize his jealousy, repair hurtful words and discover his own strengths. Some talents show up when we help, organize or encourage others. Other talents grow with practice and patience.','At the festival, Tilo celebrated his friends and shared his music. One note didn’t come out as he expected, so he breathed and carried on. His song wasn’t perfect, but it was his. Chispita’s light didn’t put out Tilo’s.'],questions:['What do you enjoy doing, and what would you like to learn with practice and patience?']},
palabras:{label:'Words and empathy',title:'The Little Angel of Words',story:['Toti won the Festival of Voices. A comment about his grandmother changed as it passed from friend to friend until it became a rumor about cheating. Tilo repeated it without checking. Toti felt hurt and stopped singing.','The little angel of words showed Tilo a garden where words could plant flowers or thorns. The angel taught him three questions before speaking: Is it true? Is it necessary? Is it kind? Tilo decided to find out what had happened.','Toti told him the truth: his grandmother had encouraged him to breathe and sing from the heart. Tilo admitted his mistake and corrected the rumor in front of everyone who had heard it. The hurt needed time, but honest words were beginning to repair it.'],questions:['How did the comment change as it passed from friend to friend?']}
};
function storyFor(key){return language==='en'?{...adventures[key],...adventuresEn[key]}:adventures[key];}
